node <<'NODE'
'use strict';
const fs=require('fs'),p=require('path');
const prep='docs/papers211_215_sequence/qa/p214_round0_preparation01';
const paper='papers/214-nilpotent-bilinear-clock';
const read=f=>fs.readFileSync(f,'utf8');
const assert=(v,m)=>{if(!v)throw Error(m);};
const names=['README.md','CLAIMS_EVIDENCE.md','NARRATIVE_REPORT.md'];
const files=read(prep+'/FILES.tsv').trimEnd().split('\n').map(l=>l.split('\t'));
assert(files.length===30&&files.every(r=>r.length===2),'map cardinality');
assert(new Set(files.map(r=>r[0])).size===30&&new Set(files.map(r=>r[1])).size===30,'map unique');
for(const [s,d]of files){assert(!p.isAbsolute(s)&&!p.isAbsolute(d)&&!s.split('/').includes('..')&&!d.split('/').includes('..'),'bounded map');}
for(const [s]of files.slice(0,28))assert(fs.lstatSync(s).isFile()&&!fs.lstatSync(s).isSymbolicLink(),'existing selected source '+s);
assert(files[28][0]===paper+'/main.pdf'&&files[29][0]==='docs/papers211_215_sequence/qa/p214_round0_binding01/FREEZE_SCOPE.md','pending roles');
const a=read('docs/papers211_215_sequence/qa/p212_round0_freeze_source01/FREEZE.proposed.sh.txt');
const expected=a.replaceAll('P212','P214').replaceAll('p212_source','p214_source').replaceAll('p212_dest','p214_dest').replace('qa/p212_round0_freeze_source01','qa/p214_round0_preparation01').replace('qa/p212_round0_freeze_binding01','qa/p214_round0_binding01').replace('papers/212-closed-pointer-orbits','papers/214-nilpotent-bilinear-clock').replace('mkdir -- "$P214_FREEZE/sections" "$P214_FREEZE/evidence"','mkdir -- "$P214_FREEZE/sections" "$P214_FREEZE/sources" "$P214_FREEZE/evidence"');
assert(read(prep+'/FREEZE.proposed.sh.txt')===expected,'exact inherited recipe delta');
const between=(s,a,b)=>s.slice(s.indexOf(a),s.indexOf(b));
const summary=[];
for(const n of names){
 const original=read(prep+'/originals/'+n),proposed=read(prep+'/proposed/'+n);
 assert(Buffer.from(original).equals(fs.readFileSync(paper+'/'+n))),'current original '+n);
 let links=0;
 for(const m of proposed.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const target=m[1];if(/^(https?:|#)/.test(target))continue;
  const resolved=p.resolve(p.dirname(paper+'/'+n),target.split('#')[0]);
  assert(resolved.startsWith(process.cwd()+'/')&&fs.existsSync(resolved),'original-base local link '+n+' '+target);links++;
 }
 if(n==='README.md'){
  assert(between(original,'## Content and limits','## Artifact roles')===between(proposed,'## Content and limits','## Artifact roles'),'README math unchanged');
  assert(between(original,'## Actual authorship and review eligibility','## Work actually done and still pending')===between(proposed,'## Actual authorship and review eligibility','## Work actually done and still pending'),'all original provenance rows unchanged');
 }
 if(n==='CLAIMS_EVIDENCE.md'){
  const rows=s=>s.split('\n').filter(l=>/^\| C[1-9]/.test(l)).map(l=>l.split('|').slice(1,4).join('|'));
  assert(JSON.stringify(rows(original))===JSON.stringify(rows(proposed))&&rows(proposed).length===7,'all seven claim/proof/manuscript rows unchanged');
 }
 if(n==='NARRATIVE_REPORT.md'){
  assert(between(original,'## The technical story','## Evidence and experiment boundary').replace('The manuscript will state','The manuscript states')===between(proposed,'## The technical story','## Evidence and experiment boundary'),'narrative complete math only tense');
 }
 assert(proposed.includes('4ebeac267f855a1f9b03263ed2517d7a34b6dd0b62639b9fa54129c136763c35'),'actual canonical identity');
 assert(proposed.includes('qa/p214_display_repair_binding01/ADOPTED_SOURCE_INPUTS.sha256'),'latest pre-lifecycle key');
 summary.push({role:n,original_bytes:Buffer.byteLength(original),proposed_bytes:Buffer.byteLength(proposed),resolved_local_links:links});
}
process.stdout.write(JSON.stringify({scope:'READ_ONLY_DOCUMENTARY_SOURCE_CHECK_NOT_SCIENCE_BUILD_FREEZE_OR_ACCEPTANCE',map_rows:30,existing_mapped_roles_read:28,pending_pdf_scope_paths_not_queried:true,recipe:'exact accepted base substitutions plus sources directory',lifecycle:summary,checks:'all complete'},null,2)+'\n');
